import{_ as a,o as e,c as n,ag as r}from"./chunks/framework.CtWPcAmt.js";const u=JSON.parse('{"title":"第 1 章：AI Agent 到底是什么","description":"用生活化比喻讲清普通聊天、Copilot 与 Agent 的区别，以及模型、上下文、工具、记忆与权限五个基本概念。","frontmatter":{"title":"第 1 章：AI Agent 到底是什么","description":"用生活化比喻讲清普通聊天、Copilot 与 Agent 的区别，以及模型、上下文、工具、记忆与权限五个基本概念。","layout":"doc","lastUpdated":true},"headers":[],"relativePath":"guide/01-what-is-an-agent.md","filePath":"guide/01-what-is-an-agent.md","lastUpdated":null}'),o={name:"guide/01-what-is-an-agent.md"};function d(l,t,i,g,h,s){return e(),n("div",null,[...t[0]||(t[0]=[r('<h1 id="第-1-章-ai-agent-到底是什么" tabindex="-1">第 1 章：AI Agent 到底是什么 <a class="header-anchor" href="#第-1-章-ai-agent-到底是什么" aria-label="Permalink to &quot;第 1 章：AI Agent 到底是什么&quot;">​</a></h1><h2 id="本章解决什么问题" tabindex="-1">本章解决什么问题 <a class="header-anchor" href="#本章解决什么问题" aria-label="Permalink to &quot;本章解决什么问题&quot;">​</a></h2><p>你天天听人说「AI Agent」，但可能说不清它和 ChatGPT 聊天框有什么区别。本章用一个贯穿全书的生活化比喻，把五个核心概念（模型、上下文、工具、记忆、权限）讲清楚，并让你画出一张<strong>Agent 工作流程图</strong>。看完后你会明白：为什么「会聊天」不等于「会干活」，以及桌面 Agent 里那个「自动完成任务」的按钮背后发生了什么。</p><h2 id="从一个真实场景开始" tabindex="-1">从一个真实场景开始 <a class="header-anchor" href="#从一个真实场景开始" aria-label="Permalink to &quot;从一个真实场景开始&quot;">​</a></h2><p>你让聊天 AI「帮我整理一下旅行照片」。它回复：「好的！你可以先按日期分类，再删除模糊的……祝旅途愉快！」——它给了你一篇攻略，但照片一张都没动。</p><p>同样一句话，如果你对桌面 Agent 说，它可能：打开你的照片文件夹 → 按日期和地点分组 → 把重复照片挑出来放到「待删除」文件夹 → 生成一份带说明的相册目录 → 告诉你「共整理 214 张，重复 37 张，说明文件在 output 目录下」。</p><p><strong>两者都能「回答」，只有后者「干活」。</strong> 这中间的差别，就是本章要讲的东西。</p><h2 id="先说结论" tabindex="-1">先说结论 <a class="header-anchor" href="#先说结论" aria-label="Permalink to &quot;先说结论&quot;">​</a></h2><ol><li><strong>Agent 的本质是「能执行任务的 AI」，聊天 AI 的本质是「能生成回答的 AI」</strong>——执行意味着它要自己规划步骤、调用工具、读写文件，并对结果负责；</li><li><strong>Agent 由五块拼图组成</strong>：模型（思考的脑子）、上下文（眼前能看到什么）、工具（能动手做什么）、记忆（长期记得什么）、权限（被允许做什么）；</li><li><strong>模型能力不是 Agent 的全部</strong>：同样的模型放在不同的 Agent 里，体验可能完全不同——因为工具、权限和验证流程是产品自己搭的（第 5 章实测会反复证明这一点）；</li><li><strong>Agent 也会犯错，而且犯错的形态和聊天 AI 不同</strong>：它可能读错文件、改错地方、或者「自信地」做了一件你没让它做的事。知道它由什么组成，你才知道该检查哪里（第 2、8、10 章展开）。</li></ol><h2 id="必要概念-用一个比喻" tabindex="-1">必要概念（用一个比喻） <a class="header-anchor" href="#必要概念-用一个比喻" aria-label="Permalink to &quot;必要概念（用一个比喻）&quot;">​</a></h2><p>把 Agent 想象成<strong>一位新入职的实习生</strong>。它有五个属性：</p><table tabindex="0"><thead><tr><th>概念</th><th>白话解释</th><th>实习生比喻</th></tr></thead><tbody><tr><td><strong>模型</strong></td><td>Agent 用来思考和生成内容的 AI 大脑</td><td>实习生的「能力水平」——学历和智商</td></tr><tr><td><strong>上下文</strong></td><td>这次任务里它能「看到」的全部信息：你的话、文件、规则</td><td>实习生眼前摊开的资料和你的口头交代</td></tr><tr><td><strong>工具</strong></td><td>它实际能调用的能力：读文件、写文件、跑计算、访问网页</td><td>实习生能用的电脑、打印机、电话</td></tr><tr><td><strong>记忆</strong></td><td>跨任务记住的长期信息：你的偏好、历史约定</td><td>实习生的笔记本和你的口头约定</td></tr><tr><td><strong>权限</strong></td><td>它被允许做的事的范围：哪些文件夹能碰、哪些操作要请示</td><td>实习生的门禁卡和「需要经理审批」的规定</td></tr></tbody></table><ul><li><strong>模型</strong>：白话解释「一个根据你输入的内容，预测并生成下一步文字的巨型程序」。正式说法：通过大规模训练学会理解和生成自然语言等内容的神经网络。它决定 Agent「想得到想不到」，但不决定它「做得到做不到」。</li><li><strong>上下文</strong>：本次任务 Agent 能看到的全部信息总和。它不能像人一样「凭记忆」——没放进上下文的信息，对它等于不存在。</li><li><strong>工具</strong>：Agent 主动调用的外部能力（文件读写、命令行、浏览器、表格）。有工具的 Agent 才能从「说话」变成「干活」。</li><li><strong>记忆</strong>：产品提供的长期存储（规则、偏好、历史）。很多产品把「记忆」做成可编辑的文件或设置项。</li><li><strong>权限</strong>：产品对 Agent 行为的限制规则。它决定 Agent 能否写文件、能否联网、哪些操作需要你点击确认。</li></ul><h2 id="三种形态-三个台阶" tabindex="-1">三种形态，三个台阶 <a class="header-anchor" href="#三种形态-三个台阶" aria-label="Permalink to &quot;三种形态，三个台阶&quot;">​</a></h2><table tabindex="0"><thead><tr><th>形态</th><th>例子</th><th>会做什么</th><th>不会做什么</th></tr></thead><tbody><tr><td>聊天 AI</td><td>ChatGPT 网页聊天</td><td>生成回答、写文案、问答</td><td>自己动你的文件、替你执行</td></tr><tr><td>Copilot（副驾驶）</td><td>编辑器里的补全助手</td><td>在你操作时给建议、补全当前内容</td><td>独立完成多步骤任务</td></tr><tr><td>Agent（智能体）</td><td>桌面 Agent（本书第 5 章七款）</td><td>接收任务、规划、调用工具、交付结果</td><td>替你承担最终责任（责任仍在人，第 3 章）</td></tr></tbody></table><p>理解台阶的意义：<strong>不是越高级越好，而是匹配任务</strong>。查一个事实用聊天 AI 最快；写代码时 Copilot 顺手；而「把一摊材料整理成六个文档」这种多步骤任务，才值得动用 Agent。</p><h2 id="跟着做-画一张-agent-工作流程图" tabindex="-1">跟着做：画一张 Agent 工作流程图 <a class="header-anchor" href="#跟着做-画一张-agent-工作流程图" aria-label="Permalink to &quot;跟着做：画一张 Agent 工作流程图&quot;">​</a></h2><p>以你序章写下的「任务种子」为例子，画出 Agent 处理它的过程：</p><h3 id="第一步-画出「人-→-agent」的输入" tabindex="-1">第一步：画出「人 → Agent」的输入 <a class="header-anchor" href="#第一步-画出「人-→-agent」的输入" aria-label="Permalink to &quot;第一步：画出「人 → Agent」的输入&quot;">​</a></h3><p>人（你）做什么：定目标、给材料、定约束、定验收标准。在纸上左侧画一个人形，箭头指向右侧的「Agent」，箭头旁写下：目标、材料、约束。</p><h3 id="第二步-画出-agent-内部的三段循环" tabindex="-1">第二步：画出 Agent 内部的三段循环 <a class="header-anchor" href="#第二步-画出-agent-内部的三段循环" aria-label="Permalink to &quot;第二步：画出 Agent 内部的三段循环&quot;">​</a></h3><p>在纸中间画一个大框（Agent），里面画三段循环：</p><ol><li><strong>理解</strong>：读目标 + 读上下文（材料、规则）；</li><li><strong>行动</strong>：调工具（读文件、生成内容、写文件）；</li><li><strong>反馈</strong>：观察结果，决定继续、修正或结束。</li></ol><p>用循环箭头把三段连起来：理解 → 行动 → 反馈 →（回到）理解。</p><h3 id="第三步-画出「agent-→-人」的交付与检查" tabindex="-1">第三步：画出「Agent → 人」的交付与检查 <a class="header-anchor" href="#第三步-画出「agent-→-人」的交付与检查" aria-label="Permalink to &quot;第三步：画出「Agent → 人」的交付与检查&quot;">​</a></h3><p>右侧再画一个人形（还是你），从 Agent 框画出输出箭头：成品、过程记录、自检说明。在旁边写一句：「我检查，我负责」。</p><h3 id="第四步-对照你用的产品-找这五块在哪" tabindex="-1">第四步：对照你用的产品，找这五块在哪 <a class="header-anchor" href="#第四步-对照你用的产品-找这五块在哪" aria-label="Permalink to &quot;第四步：对照你用的产品，找这五块在哪&quot;">​</a></h3><p>打开你已经装好的任一桌面 Agent（没有就先跳过，第 4 章会选），试着找：</p><ul><li>模型/模式：通常在设置或对话上方（如「Auto」「默认模型」）；</li><li>上下文：对话里引用文件（<code>@文件</code>）、任务描述、项目目录；</li><li>工具：任务面板里出现的「读文件」「写文件」「搜索」等动作；</li><li>记忆：产品里的「规则」「偏好」「项目配置」；</li><li>权限：设置里的「权限模式」「需要确认的操作」。</li></ul><h2 id="一个完整示例" tabindex="-1">一个完整示例 <a class="header-anchor" href="#一个完整示例" aria-label="Permalink to &quot;一个完整示例&quot;">​</a></h2><p>用我实测过的场景（第 5 章 WorkBuddy 体验页有完整记录）走一遍流程图：</p><ul><li><strong>输入</strong>：任务「整理 AI Agent 教程材料，生成六份指定文档」+ 材料包（7 个文件）+ 约束（只读 <code>input</code> 目录、输出到 <code>output</code>）+ 验收标准（6 份文件齐全、输入哈希一致）；</li><li><strong>理解</strong>：Agent 读取材料包与任务说明，规划步骤；</li><li><strong>行动</strong>：读取 7 份材料 → 逐份生成 6 份文档 → 写入 <code>output</code> → 运行自检；</li><li><strong>反馈</strong>：自检发现材料边界偏差（把裁剪输入外内容列为缺失）→ 停止并在自检中说明；</li><li><strong>交付</strong>：6 份文档 + 自检说明；人复核后发现「产物列表 6 份但变更列表只显示 5 份」的展示问题，以文件系统为准验收。</li></ul><p>这个例子说明：<strong>流程图每一步都可能出问题，而检查点（反馈 → 人复核）才是流程能闭环的关键。</strong></p><h2 id="常见错误与恢复方法" tabindex="-1">常见错误与恢复方法 <a class="header-anchor" href="#常见错误与恢复方法" aria-label="Permalink to &quot;常见错误与恢复方法&quot;">​</a></h2><table tabindex="0"><thead><tr><th>现象</th><th>可能原因</th><th>怎样修正</th></tr></thead><tbody><tr><td>以为模型强 = Agent 好用</td><td>把模型能力等同于产品能力</td><td>对照第 5 章：同样的 DeepSeek V4 Flash，不同产品体验不同</td></tr><tr><td>把聊天 AI 的对话习惯用在 Agent 上</td><td>没意识到 Agent 会「动手」</td><td>先想清楚：这次任务要不要它碰我的文件？</td></tr><tr><td>找不到「记忆」在哪里</td><td>产品术语不同（规则/偏好/项目配置）</td><td>看产品文档，或直接问它的帮助入口</td></tr><tr><td>画流程图时发现「权限」没概念</td><td>还没用过会写文件的 Agent</td><td>先读第 8 章再回来画</td></tr></tbody></table><h2 id="安全提醒" tabindex="-1">安全提醒 <a class="header-anchor" href="#安全提醒" aria-label="Permalink to &quot;安全提醒&quot;">​</a></h2><ul><li>让 Agent 动手的第一原则：<strong>先给只读权限或临时目录</strong>，确认它能正确理解范围后再逐步放开（第 8 章系统讲解）；</li><li>你的「任务种子」暂时不要包含账号密码、身份证号等敏感信息。</li></ul><h2 id="本章练习" tabindex="-1">本章练习 <a class="header-anchor" href="#本章练习" aria-label="Permalink to &quot;本章练习&quot;">​</a></h2><p>15 分钟：按「跟着做」四步画出你的 Agent 工作流程图；如果你已经装了某款桌面 Agent，找出它的五块拼图分别在界面的哪里，标注在图上。</p><h2 id="你应该带走的成果" tabindex="-1">你应该带走的成果 <a class="header-anchor" href="#你应该带走的成果" aria-label="Permalink to &quot;你应该带走的成果&quot;">​</a></h2><ul><li><strong>一张 Agent 工作流程图</strong>（可以手画或画在文档里），标注出你所用产品的五块拼图位置。</li></ul><h2 id="本章小结" tabindex="-1">本章小结 <a class="header-anchor" href="#本章小结" aria-label="Permalink to &quot;本章小结&quot;">​</a></h2><ol><li>Agent 与聊天 AI 的根本区别：执行任务，而不只是生成回答；</li><li>Agent = 模型 + 上下文 + 工具 + 记忆 + 权限；</li><li>聊天 / Copilot / Agent 是三个台阶，匹配任务才重要；</li><li>Agent 的工作是「理解 → 行动 → 反馈」的循环；</li><li>反馈与人的检查，才是流程闭环的关键。</li></ol>',43)])])}const c=a(o,[["render",d]]);export{u as __pageData,c as default};
